/* Motorcycles set additions — cards appended after motorcycles.js.
   (motorcycles.js exceeds the push size limit, so remaining cards live here instead of being
   edited into it. Must stay directly after 'motorcycles.js' in sets/manifest.js.) */
(function () {
  var S = window.CardSets && window.CardSets.get('motorcycles');
  if (!S) return;
  var extra = [{"name":"Honda CB550 Four","rarity":"uncommon","id":"honda-cb550-four","subtitle":"Japanese Sport & Standards","details":"The CB550 Four refined Honda's middleweight formula with a 544cc four, front disc and four-into-one style in a sweet-handling package.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/88/Honda_CB550Four_side.jpg/1280px-Honda_CB550Four_side.jpg"},{"name":"Kawasaki Z650","rarity":"uncommon","id":"kawasaki-z650","subtitle":"Japanese Sport & Standards","details":"The Z650, sold as the KZ650 in America, put Z1 style and a 652cc four into a lighter, friendlier middleweight that sold in huge numbers.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/07/1978_Kawasaki_KZ650_Custom_%281%29_%2823503763946%29.jpg/1280px-1978_Kawasaki_KZ650_Custom_%281%29_%2823503763946%29.jpg"},{"name":"Suzuki GS750","rarity":"uncommon","id":"suzuki-gs750","subtitle":"Japanese Sport & Standards","details":"Suzuki's GS750 was the firm's first big four-stroke four, a double-overhead-cam 748cc standard that set up the GS range's strong decade.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7e/GS750_IMG_20141123_123957b.jpg/1280px-GS750_IMG_20141123_123957b.jpg"},{"name":"Yamaha SR500","rarity":"uncommon","id":"yamaha-sr500","subtitle":"Japanese Sport & Standards","details":"The kick-start-only SR500 distilled the big single to its essentials, a 499cc thumper echoing British singles of an earlier age.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8e/SR500_-_1980.jpg/1280px-SR500_-_1980.jpg"},{"name":"Honda CB350","rarity":"uncommon","id":"honda-cb350","subtitle":"Japanese Sport & Standards","details":"The CB350 twin was Honda's best-selling model of its era, a 325cc commuter-sport twin that introduced countless riders to motorcycling.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/55/Honda_CB350_%281970%29_-_27634402624.jpg/1280px-Honda_CB350_%281970%29_-_27634402624.jpg"},{"name":"Kawasaki GPZ550","rarity":"uncommon","id":"kawasaki-gpz550","subtitle":"Japanese Sport & Standards","details":"The GPZ550 proved a middleweight could be a real sportsbike, its air-cooled four and rear suspension punching far above its size.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fc/2016-09-22_Kawasaki_GP_550_Z_%282%29.jpg/1280px-2016-09-22_Kawasaki_GP_550_Z_%282%29.jpg"},{"name":"Suzuki Bandit 1200","rarity":"uncommon","id":"suzuki-bandit-1200","subtitle":"Japanese Sport & Standards","details":"The Bandit 1200 stuffed Suzuki's oil-cooled GSX-R-derived four into a naked steel frame, a torque-rich hooligan with everyday manners.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8e/GV75A-N.jpg/1280px-GV75A-N.jpg"},{"name":"Yamaha XJ600 Seca II","rarity":"uncommon","id":"yamaha-xj600-seca-ii","subtitle":"Japanese Sport & Standards","details":"The Seca II, or Diversion abroad, wrapped a 599cc four in a neat half-fairing, an economical all-rounder aimed at new and returning riders.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/61/Yamaha-XJ600-1996.triddle.jpg/1280px-Yamaha-XJ600-1996.triddle.jpg"},{"name":"Honda CBR600RR","rarity":"uncommon","id":"honda-cbr600rr","subtitle":"Japanese Sport & Standards","details":"Honda's CBR600RR took its styling and centralised mass from the RC211V MotoGP bike, defining the focused 600 supersport of the 2000s.","image":"https://upload.wikimedia.org/wikipedia/commons/f/fd/HONDA_CBR600RR_2007TMCS.jpg"},{"name":"Kawasaki Ninja ZX-6R","rarity":"uncommon","id":"kawasaki-ninja-zx-6r","subtitle":"Japanese Sport & Standards","details":"Kawasaki's Ninja ZX-6R carried a 636cc engine option for the street in many years, a sharp supersport with extra midrange over its rivals.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/34/Kawasaki_Ninja_ZX-6R_ZX636G.jpg/1280px-Kawasaki_Ninja_ZX-6R_ZX636G.jpg"},{"name":"Suzuki RGV250","rarity":"uncommon","id":"suzuki-rgv250","subtitle":"Japanese Sport & Standards","details":"The RGV250 brought Grand Prix manners to the road, a V-twin two-stroke replica with aluminium frame and race-track focus in a 250 chassis.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9b/Suzuki_RGV250_motorcycle.jpg/1280px-Suzuki_RGV250_motorcycle.jpg"},{"name":"Yamaha TZR250","rarity":"uncommon","id":"yamaha-tzr250","subtitle":"Japanese Sport & Standards","details":"Yamaha's TZR250 racer replica delivered two-stroke Grand Prix technology, complete with YPVS power valve, to quarter-litre devotees.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/02/Yamaha_TZR250_2MA.jpg/1280px-Yamaha_TZR250_2MA.jpg"},{"name":"Honda NSR250R","rarity":"uncommon","id":"honda-nsr250r","subtitle":"Japanese Sport & Standards","details":"Honda's NSR250R V-twin two-stroke was a high-tech replica of the factory RS250 racers, a jewel of the quarter-litre grey-import scene.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e6/Honda_NSR250R_1988.jpg/1280px-Honda_NSR250R_1988.jpg"},{"name":"Kawasaki W650","rarity":"uncommon","id":"kawasaki-w650","subtitle":"Japanese Sport & Standards","details":"The W650 channelled 1960s British twins with a bevel-drive overhead cam, kick starter and air-cooled 676cc parallel twin character.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/dc/Kawasaki_W650_2000_Retro_High_Bar.jpg/1280px-Kawasaki_W650_2000_Retro_High_Bar.jpg"},{"name":"Suzuki GT750","rarity":"uncommon","id":"suzuki-gt750","subtitle":"Japanese Sport & Standards","details":"The GT750's liquid-cooled two-stroke triple, the 'Water Buffalo', offered turbine smoothness and touring comfort as a three-cylinder pioneer.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/00/1971_Suzuki_GT750_at_Suzuki_Plaza.jpg/1280px-1971_Suzuki_GT750_at_Suzuki_Plaza.jpg"},{"name":"Yamaha RD400","rarity":"uncommon","id":"yamaha-rd400","subtitle":"Japanese Sport & Standards","details":"The RD400 grew the RD formula with more cubes, cast wheels and a rear disc, the definitive air-cooled two-stroke street racer of the 1970s.","image":"https://upload.wikimedia.org/wikipedia/commons/b/b7/Yamaha_RD400_DX_1978.jpg"},{"name":"Honda CB77 Super Hawk","rarity":"uncommon","id":"honda-cb77-super-hawk","subtitle":"Japanese Sport & Standards","details":"The CB77 Super Hawk was Honda's first true sportsbike, a 305cc twin whose speed and reliability humbled larger British rivals of the 1960s.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a5/Honda_CB77_Super_Hawk_%281964%29_-_29086471981.jpg/1280px-Honda_CB77_Super_Hawk_%281964%29_-_29086471981.jpg"},{"name":"Kawasaki KZ750","rarity":"uncommon","id":"kawasaki-kz750","subtitle":"Japanese Sport & Standards","details":"The KZ750 four gave Kawasaki buyers big-Z style in a cheaper, lighter package, and sired the company's long-lived 750 standard line.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/21/Kawasaki_KZ750_de_1980.jpg/1280px-Kawasaki_KZ750_de_1980.jpg"},{"name":"Suzuki GS500","rarity":"uncommon","id":"suzuki-gs500","subtitle":"Japanese Sport & Standards","details":"The GS500's air-cooled parallel twin and simple chassis made it a training-school staple and a first big bike for a generation of riders.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c6/SuzukiGS500.JPG/1280px-SuzukiGS500.JPG"},{"name":"Yamaha FZ6","rarity":"uncommon","id":"yamaha-fz6","subtitle":"Japanese Sport & Standards","details":"Yamaha's FZ6 retuned the R6 engine for the road, a half-faired middleweight all-rounder that became a commuter favourite of the 2000s.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/08/2005_Yamaha_FZ6.jpg/1280px-2005_Yamaha_FZ6.jpg"},{"name":"Honda CB600F Hornet","rarity":"uncommon","id":"honda-cb600f-hornet","subtitle":"Japanese Sport & Standards","details":"The CB600F Hornet borrowed the CBR600's four and wore it naked, a cheeky middleweight named for its tail-up, insect-like stance.","image":"https://upload.wikimedia.org/wikipedia/commons/4/49/Honda_CB600F_Hornet_1998_PC34.jpg"},{"name":"Kawasaki ER-6n","rarity":"uncommon","id":"kawasaki-er-6n","subtitle":"Japanese Sport & Standards","details":"Kawasaki's ER-6n put the Ninja 650's parallel twin in a naked chassis with an off-centre rear shock, a friendly and funky commuter.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8b/2023-08_Kawasaki_ER-6n_right%2C_Empuria_Brava%2C_North_of_spain.jpg/1280px-2023-08_Kawasaki_ER-6n_right%2C_Empuria_Brava%2C_North_of_spain.jpg"},{"name":"Suzuki Gladius","rarity":"uncommon","id":"suzuki-gladius","subtitle":"Japanese Sport & Standards","details":"The Gladius restyled Suzuki's SV650 V-twin formula with a curvy trellis frame and fashion-led design aimed at new middleweight buyers.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6a/Suzuki_Gladius_with_helmet.jpg/1280px-Suzuki_Gladius_with_helmet.jpg"},{"name":"Honda CRF450RL","rarity":"uncommon","id":"honda-crf450rl","subtitle":"Dirt, Adventure & Off-Road","details":"Honda's CRF450RL is a road-legal dual-sport closely based on the CRF450X enduro racer, with a 449cc single made for trails and tarmac alike.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/37/CRF450RL.jpg/1280px-CRF450RL.jpg"},{"name":"Honda XL750 Transalp","rarity":"uncommon","id":"honda-xl750-transalp","subtitle":"Dirt, Adventure & Off-Road","details":"The XL750 Transalp revived Honda's famous adventure name with a 755cc parallel twin, a 21-inch front wheel and a rally-style fairing.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/88/2023_Honda_XL750_Transalp.jpg/1280px-2023_Honda_XL750_Transalp.jpg"},{"name":"Suzuki DR-Z400S","rarity":"uncommon","id":"suzuki-dr-z400s","subtitle":"Dirt, Adventure & Off-Road","details":"Suzuki's DR-Z400S is a 398cc liquid-cooled dual-sport single, a long-running favorite for commuting on weekdays and riding trails on weekends.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/79/2010_Suzuki_DRZ400_at_the_2009_Seattle_International_Motorcycle_Show_2.jpg/1280px-2010_Suzuki_DRZ400_at_the_2009_Seattle_International_Motorcycle_Show_2.jpg"},{"name":"Suzuki DR350S","rarity":"uncommon","id":"suzuki-dr350s","subtitle":"Dirt, Adventure & Off-Road","details":"The DR350S gave Suzuki riders a light 349cc air-cooled dual-sport, a simple and tough trail machine with a strong following among new riders.","image":"https://upload.wikimedia.org/wikipedia/commons/5/50/Suzuki_DR350S_1990.jpg"},{"name":"Kawasaki KLX250","rarity":"uncommon","id":"kawasaki-klx250","subtitle":"Dirt, Adventure & Off-Road","details":"Kawasaki's KLX250 is a light 249cc liquid-cooled dual-sport, also used in camouflage form as a reconnaissance bike by Japan's Self-Defense Forces.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e6/Klx250.jpg/1280px-Klx250.jpg"},{"name":"Yamaha XT1200Z Super Ténéré","rarity":"uncommon","id":"yamaha-xt1200z-super-tenere","subtitle":"Dirt, Adventure & Off-Road","details":"Yamaha's Super Ténéré is a 1,199cc parallel-twin shaft-drive adventure tourer, Yamaha's heavyweight answer to the big European GS machines.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/43/Yamaha_XT_1200_Z_Super_T%C3%A9n%C3%A9r%C3%A9.jpg/1280px-Yamaha_XT_1200_Z_Super_T%C3%A9n%C3%A9r%C3%A9.jpg"},{"name":"KTM 890 Adventure","rarity":"uncommon","id":"ktm-890-adventure","subtitle":"Dirt, Adventure & Off-Road","details":"KTM's 890 Adventure uses an 889cc parallel twin in a low-slung chassis, its fuel tank wrapped low around the engine for better dirt handling.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/37/KTM_890_Adventure.jpg/1280px-KTM_890_Adventure.jpg"},{"name":"BMW G 310 GS","rarity":"uncommon","id":"bmw-g-310-gs","subtitle":"Dirt, Adventure & Off-Road","details":"The smallest GS, BMW's G 310 GS is a 313cc single-cylinder adventure-styled learner bike, built in India by TVS alongside the G 310 R.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d3/BMW_G310_GS_2023-08.jpg/1280px-BMW_G310_GS_2023-08.jpg"},{"name":"BMW R 1250 GS","rarity":"uncommon","id":"bmw-r-1250-gs","subtitle":"Dirt, Adventure & Off-Road","details":"The R 1250 GS introduced BMW's ShiftCam variable valve timing to the 1,254cc boxer twin, keeping the big GS at the head of the adventure class.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/44/BMW_R1250GS_HP_2018-10-12.jpg/1280px-BMW_R1250GS_HP_2018-10-12.jpg"},{"name":"Triumph Scrambler 1200 XE","rarity":"uncommon","id":"triumph-scrambler-1200-xe","subtitle":"Dirt, Adventure & Off-Road","details":"Triumph's Scrambler 1200 XE pairs a 1,200cc Bonneville twin with long-travel suspension and real off-road hardware under retro styling.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/16/Scrambler1200xe.jpg/1280px-Scrambler1200xe.jpg"},{"name":"KTM 790 Adventure","rarity":"uncommon","id":"ktm-790-adventure","subtitle":"Dirt, Adventure & Off-Road","details":"KTM's 790 Adventure brought the LC8c 799cc parallel twin to middleweight adventure riding, with a distinctive low-mounted fuel tank design.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/87/KTM_790_Adventure.jpg/1280px-KTM_790_Adventure.jpg"},{"name":"Honda CRF250L","rarity":"uncommon","id":"honda-crf250l","subtitle":"Dirt, Adventure & Off-Road","details":"Honda's CRF250L is a friendly 249cc dual-sport single, styled after the CRF450R motocrosser and popular as a first trail bike around the world.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/06/Honda_CRF250L.jpg/960px-Honda_CRF250L.jpg"},{"name":"BMW F 800 GS","rarity":"uncommon","id":"bmw-f-800-gs","subtitle":"Dirt, Adventure & Off-Road","details":"BMW's F 800 GS is a middleweight adventurer with a 798cc parallel twin and a 21-inch front wheel, built for genuine trail ability.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/84/Liesel_14-11-10_BMW_F_800_GS_01-2.JPG/1280px-Liesel_14-11-10_BMW_F_800_GS_01-2.JPG"},{"name":"BMW R 1150 GS","rarity":"uncommon","id":"bmw-r-1150-gs","subtitle":"Dirt, Adventure & Off-Road","details":"The R 1150 GS grew BMW's boxer adventurer to 1,130cc, and in Adventure form, with a huge 30-litre tank, became a round-the-world favorite.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9a/BMW_R1150GS.JPG/1280px-BMW_R1150GS.JPG"},{"name":"Husqvarna Norden 901","rarity":"uncommon","id":"husqvarna-norden-901","subtitle":"Dirt, Adventure & Off-Road","details":"Husqvarna's Norden 901 is a premium travel take on KTM's 890 platform, an 889cc parallel twin wrapped in rounded, Scandinavian-styled bodywork.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f5/Husqvarna_901_Norden.jpg/1280px-Husqvarna_901_Norden.jpg"},{"name":"Yamaha WR250R","rarity":"uncommon","id":"yamaha-wr250r","subtitle":"Dirt, Adventure & Off-Road","details":"Yamaha's WR250R is a high-spec 249cc dual-sport with an aluminum frame and adjustable suspension, the flagship of the small-bore WR line.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4d/YAMAHA_WR250R.jpg/1280px-YAMAHA_WR250R.jpg"},{"name":"Honda Grom","rarity":"uncommon","id":"honda-grom","subtitle":"Scooters, Minis & Oddballs","details":"Honda's Grom packs a 125cc single into a miniature naked bike, and its small, friendly size made it a favorite of new riders and customizers.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/fa/2020_Honda_MSX_Grom_125_Standard.jpg/960px-2020_Honda_MSX_Grom_125_Standard.jpg"},{"name":"Honda CT125 Hunter Cub","rarity":"uncommon","id":"honda-ct125-hunter-cub","subtitle":"Scooters, Minis & Oddballs","details":"The CT125 Hunter Cub revives Honda's trail Cub formula with a 125cc single and high exhaust; North America knows the same bike as the Trail 125.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/2e/Osaka_Auto_Messe_2022_%2882%29_-_Honda_CT125_Hunter_Cub_Mid-year_2022.jpg/960px-Osaka_Auto_Messe_2022_%2882%29_-_Honda_CT125_Hunter_Cub_Mid-year_2022.jpg"},{"name":"Honda Ruckus","rarity":"uncommon","id":"honda-ruckus","subtitle":"Scooters, Minis & Oddballs","details":"Honda's Ruckus strips the scooter to a bare frame with twin headlights and fat tires, leaving its battery box and under-seat space exposed.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/bb/Honda_Ruckus_white.jpg/960px-Honda_Ruckus_white.jpg"},{"name":"Vespa PX 150","rarity":"uncommon","id":"vespa-px-150","subtitle":"Scooters, Minis & Oddballs","details":"The PX kept Vespa's classic formula alive for decades: a steel body, a geared 150cc two-stroke and a spare wheel under the side panel.","image":"https://upload.wikimedia.org/wikipedia/commons/e/ed/Piaggio_Vespa_PX_150.jpg"},{"name":"Vespa Primavera 125","rarity":"uncommon","id":"vespa-primavera-125","subtitle":"Scooters, Minis & Oddballs","details":"The original Primavera put Vespa's smallframe on the map in 125cc form, a light and quick scooter aimed at young riders of the late 1960s.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f5/Vespa_Primavera_125.jpg/960px-Vespa_Primavera_125.jpg"},{"name":"Lambretta LI 150","rarity":"uncommon","id":"lambretta-li-150","subtitle":"Scooters, Minis & Oddballs","details":"Innocenti's LI 150 slimstyle gave Lambretta its clean 1960s look, with a 148cc two-stroke engine mounted in the center of the frame.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c1/Innocenti-Lambretta-150LI-1963.jpg/960px-Innocenti-Lambretta-150LI-1963.jpg"},{"name":"Yamaha BW'S 125","rarity":"uncommon","id":"yamaha-bws-125","subtitle":"Scooters, Minis & Oddballs","details":"Yamaha's BW'S 125 is a rugged scooter with blocky tires and dual headlights; North American riders know the same machine as the Zuma 125.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/7f/2024_Yamaha_BWS_125_motorcycle.jpg/960px-2024_Yamaha_BWS_125_motorcycle.jpg"},{"name":"Honda PCX 150","rarity":"uncommon","id":"honda-pcx-150","subtitle":"Scooters, Minis & Oddballs","details":"Honda's PCX pairs sleek maxi-scooter styling with a frugal 150cc-class single, underseat storage and an easy step-through layout.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/57/Honda_PCX_150_2012_01.jpg/960px-Honda_PCX_150_2012_01.jpg"},{"name":"Honda Helix","rarity":"uncommon","id":"honda-helix","subtitle":"Scooters, Minis & Oddballs","details":"Honda's Helix stretched the scooter into a low, long cruiser with a 244cc single, an integrated trunk and feet-forward comfort.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/74/Honda_Helix.jpg/960px-Honda_Helix.jpg"},{"name":"Harley-Davidson MC-65","rarity":"uncommon","id":"harley-davidson-mc-65","subtitle":"Scooters, Minis & Oddballs","details":"Harley's MC-65 was a 65cc two-stroke minibike from the AMF era, built in Italy by Aermacchi and sold as a pint-size Harley-Davidson.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/e/ec/Harley-Davidson_Museum_May_2024_09_%28The_AMF_Years--1972_MC-65_minibike--Two-Cycle_Single%29.jpg/960px-Harley-Davidson_Museum_May_2024_09_%28The_AMF_Years--1972_MC-65_minibike--Two-Cycle_Single%29.jpg"},{"name":"Kawasaki Z125 Pro","rarity":"uncommon","id":"kawasaki-z125-pro","subtitle":"Scooters, Minis & Oddballs","details":"Kawasaki's Z125 Pro answers the mini-moto craze with a 125cc single, an under-engine exhaust and sharp Z-family styling in a compact frame.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/98/Kawasaki_Z125_pro.jpg/960px-Kawasaki_Z125_pro.jpg"},{"name":"Fonzie's Triumph Trophy 500","rarity":"uncommon","id":"fonzies-triumph-trophy-500","subtitle":"Famous & Movie Bikes","details":"Arthur Fonzarelli's customized 1949 Triumph Trophy 500 defined cool on Happy Days, with buckhorn bars, silver tank and no front fender.","image":"https://ultimatemotorcycling.com/wp-content/uploads/2021/12/the-fonz-triumph-sold-at-auction-bonhams-tmc-1949-trophy-500-3.jpg"},{"name":"The World's Fastest Indian Special","rarity":"uncommon","id":"worlds-fastest-indian-special","subtitle":"Famous & Movie Bikes","details":"Burt Munro's streamlined Indian Special chases 200 mph at Bonneville in The World's Fastest Indian, with Anthony Hopkins as the stubborn Kiwi speedster.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/71/Burt_Munro%27s_Indian_Special_replica_from_the_movie_%22The_world%27s_Fastest_Indian%22.jpg/1280px-Burt_Munro%27s_Indian_Special_replica_from_the_movie_%22The_world%27s_Fastest_Indian%22.jpg"},{"name":"CHiPs Kawasaki KZ1000P","rarity":"uncommon","id":"chips-kawasaki-kz1000p","subtitle":"Famous & Movie Bikes","details":"Ponch and Jon patrolled LA's freeways on Kawasaki KZ1000 police bikes in CHiPs, the TV series that made the white KZP a small-screen icon.","image":"https://code3garage.com/wp-content/uploads/2023/10/california_highway_patrol_chips_kawasaki_motorcycles_200.jpg"},{"name":"Ghost Rider: Spirit of Vengeance V-Max","rarity":"uncommon","id":"ghost-rider-spirit-of-vengeance-vmax","subtitle":"Famous & Movie Bikes","details":"Johnny Blaze rides a charred Yamaha V-Max in Ghost Rider: Spirit of Vengeance, a burnt-metal brute for the rider who sold his soul.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8c/Ghost_Rider-_Spirit_of_Vengeance_motorcycle_at_Arclight_Beach_Cities_%286951060227%29.jpg/1280px-Ghost_Rider-_Spirit_of_Vengeance_motorcycle_at_Arclight_Beach_Cities_%286951060227%29.jpg"},{"name":"Sons of Anarchy Harley Dyna","rarity":"uncommon","id":"sons-of-anarchy-harley-dyna","subtitle":"Famous & Movie Bikes","details":"Jax Teller's matte black Harley-Davidson Dyna, with its club fairing and drag bars, became the defining silhouette of Sons of Anarchy.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ad/Fan_Expo_2014_-_Sons_of_Anarchy_%289669634874%29.jpg/1280px-Fan_Expo_2014_-_Sons_of_Anarchy_%289669634874%29.jpg"},{"name":"Terminator 3 Indian Chief Police Bike","rarity":"uncommon","id":"terminator-3-indian-chief-police","subtitle":"Famous & Movie Bikes","details":"The T-850 commandeers this Indian Chief police motorcycle for the crane-truck chase in Terminator 3: Rise of the Machines.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/51/The_frontview_of_Indian_Chief_Police_Motorcycle_in_Terminator_3%EF%BC%9ARise_of_the_Machines.jpg/1280px-The_frontview_of_Indian_Chief_Police_Motorcycle_in_Terminator_3%EF%BC%9ARise_of_the_Machines.jpg"},{"name":"Indiana Jones BMW Sidecar Outfit","rarity":"uncommon","id":"indiana-jones-bmw-sidecar","subtitle":"Famous & Movie Bikes","details":"Indy and his father flee the Nazis on a stolen BMW motorcycle and sidecar in Indiana Jones and the Last Crusade, escaping toward Berlin and beyond.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1f/The_frontview_of_BMW_Motorcycle_with_Sidecar_in_Indiana_Jones_and_the_Last_Crusade.jpg/1280px-The_frontview_of_BMW_Motorcycle_with_Sidecar_in_Indiana_Jones_and_the_Last_Crusade.jpg"},{"name":"Roustabout Honda CB77","rarity":"uncommon","id":"roustabout-honda-cb77","subtitle":"Famous & Movie Bikes","details":"Elvis Presley rides this red Honda CB77 Super Hawk as a carnival hand in Roustabout, the 1964 film where the King swaps hip shakes for fairground thrills.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1b/Honda_CB77_from_the_movie_%22Roustabout%22_%281964%29.jpg/1280px-Honda_CB77_from_the_movie_%22Roustabout%22_%281964%29.jpg"},{"name":"Priest Movie Motorcycle","rarity":"uncommon","id":"priest-movie-motorcycle","subtitle":"Famous & Movie Bikes","details":"The vampire-hunting Priest rides this dust-blasted, bat-winged cruiser across the wastelands in Priest, the 2011 post-apocalyptic western.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4a/Comic-Con_2010_-_Priest_3D_movie_motorcycle_%284858994465%29.jpg/1280px-Comic-Con_2010_-_Priest_3D_movie_motorcycle_%284858994465%29.jpg"},{"name":"Top Gun Maverick Kawasaki Ninja H2","rarity":"uncommon","id":"top-gun-maverick-ninja-h2","subtitle":"Famous & Movie Bikes","details":"Maverick's supercharged Kawasaki Ninja H2 Carbon streaks past the Darkstar hangar in Top Gun: Maverick, the new jet-age partner to his old GPZ.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ac/Kawasaki_Ninja_H2_CARBON_used_in_Top_Gun%EF%BC%9AMaverick.jpg/1280px-Kawasaki_Ninja_H2_CARBON_used_in_Top_Gun%EF%BC%9AMaverick.jpg"},{"name":"Terminator Salvation Moto-Terminator","rarity":"uncommon","id":"terminator-salvation-moto-terminator","subtitle":"Famous & Movie Bikes","details":"Skynet's Moto-Terminators hunt John Connor in Terminator Salvation, Ducati-based hunter-killers with guns for arms and no rider at all.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e4/Petersen_Automotive_Museum_%2852193582662%29.jpg/1280px-Petersen_Automotive_Museum_%2852193582662%29.jpg"},{"name":"Skyfall Honda CRF250","rarity":"uncommon","id":"skyfall-honda-crf250","subtitle":"Famous & Movie Bikes","details":"Bond commandeers a Honda CRF250 for Skyfall's Istanbul rooftop chase, leaping through a bazaar window in the film's breathless opening sequence.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/84/Honda_CRF250R_%28Skyfall%29_front_National_Motor_Museum%2C_Beaulieu.jpg/1280px-Honda_CRF250R_%28Skyfall%29_front_National_Motor_Museum%2C_Beaulieu.jpg"},{"name":"Rollie Free's Vincent Black Shadow","rarity":"uncommon","id":"rollie-free-vincent-black-shadow","subtitle":"Famous & Movie Bikes","details":"Rollie Free rode this stripped Vincent in just a swimsuit at Bonneville in 1948, hitting 150 mph for the most famous photo in speed-record history.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f7/1948_Vincent_Black_Shadow_Special_%22Rollie_Free%22_bikini_bike_%283828423227%29.jpg/1280px-1948_Vincent_Black_Shadow_Special_%22Rollie_Free%22_bikini_bike_%283828423227%29.jpg"},{"name":"Harley-Davidson Silent Gray Fellow","rarity":"uncommon","id":"harley-davidson-silent-gray-fellow","subtitle":"Historic Pioneers","details":"Harley's early single earned the 'Silent Gray Fellow' name from its grey paint and quiet muffling, a gentlemanly machine sold from 1911.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/42/1911HarleyDavidson%22SilentGrayFellow%22.jpg/1280px-1911HarleyDavidson%22SilentGrayFellow%22.jpg"},{"name":"Harley-Davidson Model W Sport Twin","rarity":"uncommon","id":"harley-davidson-model-w-sport-twin","subtitle":"Historic Pioneers","details":"The 1919 Sport Twin broke with Harley tradition, using a 584cc flat-twin in a light, smooth middleweight aimed at new and returning riders.","image":"https://upload.wikimedia.org/wikipedia/commons/e/e0/1919_Harley-Davidson_Model_W_Sport_Twin_%281%29_-_The_Art_of_the_Motorcycle_-_Memphis.jpg"},{"name":"Harley-Davidson VL","rarity":"uncommon","id":"harley-davidson-vl","subtitle":"Historic Pioneers","details":"The VL replaced the JD as Harley's big twin for 1930, its 1,200cc side-valve V-twin and stronger frame built for sidecar and highway work.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/79/Harley-Davidson_Museum_December_2023_15_%281932_VL--Side-Valve_V-Twin%29.jpg/1280px-Harley-Davidson_Museum_December_2023_15_%281932_VL--Side-Valve_V-Twin%29.jpg"},{"name":"Henderson KJ Streamline","rarity":"uncommon","id":"henderson-kj-streamline","subtitle":"Historic Pioneers","details":"The 1929 KJ Streamline's 1,305cc four wore flowing, enclosed styling, making it among the fastest American machines of its day.","image":"https://upload.wikimedia.org/wikipedia/commons/e/e3/Henderson_KJ_Streamline_1305_cc_1931.jpg"},{"name":"Norton Model 18","rarity":"uncommon","id":"norton-model-18","subtitle":"Historic Pioneers","details":"Norton's 490cc overhead-valve Model 18, sold from 1922, was a sturdy sporting single that became a mainstay of British roads and trials.","image":"https://upload.wikimedia.org/wikipedia/commons/3/30/Norton_Model_18_1927.jpg"},{"name":"Triumph Model H","rarity":"uncommon","id":"triumph-model-h","subtitle":"Historic Pioneers","details":"The 550cc Model H was the British Army's despatch-rider mount of the First World War, earning Triumph the nickname 'Trusty' from its riders.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bf/Triumph_Model_H_%281915%29_-_9136583051.jpg/1280px-Triumph_Model_H_%281915%29_-_9136583051.jpg"},{"name":"Scott Flying Squirrel","rarity":"uncommon","id":"scott-flying-squirrel","subtitle":"Historic Pioneers","details":"The Flying Squirrel kept Scott's water-cooled two-stroke twin and telescopic forks, a quick, unconventional Yorkshire sports machine.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d2/Scott_Flying_Squirrel_600cc_%281939%29_-_15714821449.jpg/1280px-Scott_Flying_Squirrel_600cc_%281939%29_-_15714821449.jpg"},{"name":"Rudge Ulster","rarity":"uncommon","id":"rudge-ulster","subtitle":"Historic Pioneers","details":"Named for Graham Walker's 1928 Ulster Grand Prix win at over 80 mph, the 500cc Ulster was Rudge's flagship four-valve sporting single.","image":"https://upload.wikimedia.org/wikipedia/commons/b/ba/Rudge_Ulster_Sport%2C_500_ccm%2C_Bj._1938.jpg"},{"name":"BMW R42","rarity":"uncommon","id":"bmw-r42","subtitle":"Historic Pioneers","details":"Successor to the R32, the 1926 R42 kept the 494cc flat-twin and shaft drive with a stronger frame and improved brakes, refining the formula.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/78/BMW_R42_%281928%29.jpg/1280px-BMW_R42_%281928%29.jpg"},{"name":"Moto Guzzi Normale","rarity":"uncommon","id":"moto-guzzi-normale","subtitle":"Historic Pioneers","details":"Moto Guzzi's first production model, the 1921 Normale, mounted a 499cc horizontal single in Carlo Guzzi's new factory at Mandello del Lario.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f9/Moto_Guzzi_Normale_500_%28right_view%29.jpg/1280px-Moto_Guzzi_Normale_500_%28right_view%29.jpg"},{"name":"Velocette KSS","rarity":"uncommon","id":"velocette-kss","subtitle":"Historic Pioneers","details":"The KSS was Velocette's 350cc overhead-cam sporting single - the name from K, for camshaft, and Super Sports - a jewel from Hall Green.","image":"https://upload.wikimedia.org/wikipedia/commons/0/0c/Velocette_1933_KSS.jpg"},{"name":"Harley-Davidson Street 750","rarity":"common","id":"harley-davidson-street-750","subtitle":"American Cruisers","details":"The Street 750 was Harley's global entry bike, built around the liquid-cooled Revolution X V-twin and tuned for city traffic and new riders.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/22/2014_Harley-Davidson_Street_750_side_view.jpg/1280px-2014_Harley-Davidson_Street_750_side_view.jpg"},{"name":"Harley-Davidson Street Rod","rarity":"common","id":"harley-davidson-street-rod","subtitle":"American Cruisers","details":"The Street Rod sharpened the Street 750 with a higher-output Revolution X engine, inverted forks, flat drag bars and taller, sportier geometry.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c8/Harley-Davidson_Street_Rod_%281%29.jpg/1280px-Harley-Davidson_Street_Rod_%281%29.jpg"},{"name":"Harley-Davidson 883 Roadster","rarity":"common","id":"harley-davidson-883-roadster","subtitle":"American Cruisers","details":"The XL883R Roadster wore twin front discs, orange-and-black racing paint and a 19-inch front wheel, a Sportster with a track accent.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2d/Xl883r.jpg/1280px-Xl883r.jpg"},{"name":"Harley-Davidson Sportster Roadster","rarity":"common","id":"harley-davidson-sportster-roadster","subtitle":"American Cruisers","details":"The 2016 Roadster sharpened the Sportster with inverted forks, dual front discs, taller suspension and a cafe-influenced cut-down rear fender.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/65/2016-HD-Roadster.jpg/1280px-2016-HD-Roadster.jpg"},{"name":"Indian Super Chief","rarity":"common","id":"indian-super-chief","subtitle":"American Cruisers","details":"The Super Chief pairs Indian's Thunder Stroke cruiser chassis with a windshield and leather saddlebags for light touring out of the box.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ae/The_frontview_of_Indian_Motorcycle_Super_Chief_Limited_mid-year_2023.jpg/1280px-The_frontview_of_Indian_Motorcycle_Super_Chief_Limited_mid-year_2023.jpg"},{"name":"Victory Octane","rarity":"common","id":"victory-octane","subtitle":"American Cruisers","details":"The Victory Octane was a sharper Scout-platform cousin, a 104-horsepower liquid-cooled cruiser that became one of the brand's last new models.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/ab/Motorcycle_2017_octane.jpg/1280px-Motorcycle_2017_octane.jpg"},{"name":"Victory Vision","rarity":"common","id":"victory-vision","subtitle":"American Cruisers","details":"The Victory Vision was a radical full-dress tourer whose long, sculpted bodywork and vast luggage space made it the most distinctive Victory built.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a3/Victory_Vision_Barber.jpg/1280px-Victory_Vision_Barber.jpg"},{"name":"Harley-Davidson Fat Boy 114","rarity":"common","id":"harley-davidson-fat-boy-114","subtitle":"American Cruisers","details":"The Fat Boy 114 brought the Milwaukee-Eight to the original solid-wheel icon, with satin chrome finishes and a steamroller front end for 2018.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/99/Harley_Davidson_Fat_Boy_2018_FLFBS.jpg/1280px-Harley_Davidson_Fat_Boy_2018_FLFBS.jpg"},{"name":"Boss Hoss V8","rarity":"common","id":"boss-hoss-v8","subtitle":"American Cruisers","details":"Boss Hoss builds cruisers around Chevrolet small-block and big-block V8 car engines, with two-speed semi-automatic transmissions to match.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a0/Boss_Hoss_V8_motorcycle.jpg/1280px-Boss_Hoss_V8_motorcycle.jpg"},{"name":"Harley-Davidson Sportster Hugger","rarity":"common","id":"harley-davidson-sportster-hugger","subtitle":"American Cruisers","details":"The Sportster Hugger lowered the standard XLH with shorter suspension and a stepped seat to bring the Sportster within reach of shorter riders.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2d/HD_883_Hugger.JPG/1280px-HD_883_Hugger.JPG"},{"name":"Harley-Davidson FXR","rarity":"common","id":"harley-davidson-fxr","subtitle":"American Cruisers","details":"The FXR Super Glide II earned a quiet cult reputation for its stiff triangulated frame, widely rated the best-handling chassis Harley had built.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cb/Harley_Davidson_FXRS.jpg/1280px-Harley_Davidson_FXRS.jpg"},{"name":"Harley-Davidson Servicar","rarity":"common","id":"harley-davidson-servicar","subtitle":"American Cruisers","details":"The Servi-Car was Harley's three-wheeled utility box trike, sold to police and delivery fleets from 1932 all the way through 1973.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/94/Harley-Davidson_Museum_December_2023_38_%281947_Model_G_Servi-Car_Police--Side-Valve_V-Twin%29.jpg/1280px-Harley-Davidson_Museum_December_2023_38_%281947_Model_G_Servi-Car_Police--Side-Valve_V-Twin%29.jpg"},{"name":"Harley-Davidson WLA","rarity":"common","id":"harley-davidson-wla","subtitle":"American Cruisers","details":"The WLA was Harley's wartime flathead, built in the tens of thousands for Allied service and later a surplus-bike foundation of postwar riding culture.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/49/Harley-Davidson_Museum_December_2023_61_%281942_WLA--Side-Valve_V-Twin%29.jpg/1280px-Harley-Davidson_Museum_December_2023_61_%281942_WLA--Side-Valve_V-Twin%29.jpg"},{"name":"Harley-Davidson Model J","rarity":"common","id":"harley-davidson-model-j","subtitle":"American Cruisers","details":"The Model J was Harley's flagship V-twin of the 1910s and 1920s, a 1000cc F-head twin with electric lighting and a three-speed gearbox.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/00/Harley-Davidson_Museum_December_2023_07_%281915_Model_11-J--F-Head_V-Twin%29.jpg/1280px-Harley-Davidson_Museum_December_2023_07_%281915_Model_11-J--F-Head_V-Twin%29.jpg"},{"name":"Harley-Davidson Street 500","rarity":"common","id":"harley-davidson-street-500","subtitle":"American Cruisers","details":"The Street 500 was the smallest Harley of its era, a 494cc Revolution X V-twin built for rider-training schools and first-time Harley owners worldwide.","image":"https://upload.wikimedia.org/wikipedia/commons/8/89/Harley_Davidson_street_500.jpg"},{"name":"Harley-Davidson LiveWire","rarity":"common","id":"harley-davidson-livewire","subtitle":"American Cruisers","details":"The LiveWire was Harley-Davidson's first production electric motorcycle, trading the V-twin rumble for instant electric torque and a cast alloy frame.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/38/Harley_Davidson_LiveWire_right_noBG.jpg/1280px-Harley_Davidson_LiveWire_right_noBG.jpg"},{"name":"Indian FTR 1200","rarity":"common","id":"indian-ftr-1200","subtitle":"American Cruisers","details":"The FTR 1200 carried Indian's flat-track racing success to the street with a 1203cc V-twin, a trellis frame and tracker styling from the FTR750 racer.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/ba/Indian_FTR1200.jpg/1280px-Indian_FTR1200.jpg"},{"name":"Harley-Davidson Road Glide","rarity":"common","id":"harley-davidson-road-glide","subtitle":"American Cruisers","details":"The Road Glide's shark-nose fairing is mounted to the frame rather than the forks, a signature layout Harley has kept on its touring line for decades.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a4/Harley-Davidson_Museum_May_2024_20_%281998_FLTRI_Road_Glide--OHV_V-Twin%29.jpg/1280px-Harley-Davidson_Museum_May_2024_20_%281998_FLTRI_Road_Glide--OHV_V-Twin%29.jpg"},{"name":"Harley-Davidson RL","rarity":"common","id":"harley-davidson-rl","subtitle":"American Cruisers","details":"The RL 45 was Harley's middleweight flathead solo of the 1930s, a 750cc side-valve twin that also formed the basis of the Servi-Car.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/01/1936_Harley-Davidson_RL_45.jpg/1280px-1936_Harley-Davidson_RL_45.jpg"},{"name":"Harley-Davidson KH","rarity":"common","id":"harley-davidson-kh","subtitle":"American Cruisers","details":"The KH was the final development of Harley's K-series flathead, a 750cc side-valve sport twin built only from 1954 to 1956.","image":"https://upload.wikimedia.org/wikipedia/commons/6/60/Harley_Davidson_KH_Flathead_1955_RSide_Lake_Mirror_Cassic_16Oct2010_%2814874685254%29.jpg"},{"name":"Harley-Davidson K Model","rarity":"common","id":"harley-davidson-k-model","subtitle":"American Cruisers","details":"The 1952 Model K introduced Harley's unit-construction flathead sport bike, the direct ancestor of the Sportster line that followed in 1957.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d2/Harley-Davidson_Museum_April_2024_28_%281952_Model_K--Side-Valve_V-Twin%29.jpg/1280px-Harley-Davidson_Museum_April_2024_28_%281952_Model_K--Side-Valve_V-Twin%29.jpg"},{"name":"Indian Pursuit","rarity":"common","id":"indian-pursuit","subtitle":"American Cruisers","details":"The Pursuit is Indian's liquid-cooled flagship tourer, built on the Challenger platform with a frame-mounted fairing, a top trunk and hard luggage.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/d5/Indian_Pursuit_parked_at_Hogs_for_Hospice%2C_Leamington%2C_Ontario%2C_2025-08-02.jpg/1280px-Indian_Pursuit_parked_at_Hogs_for_Hospice%2C_Leamington%2C_Ontario%2C_2025-08-02.jpg"},{"name":"Victory High-Ball","rarity":"common","id":"victory-high-ball","subtitle":"American Cruisers","details":"The High-Ball was Victory's factory bobber: ape-hanger bars, whitewall tires on spoked wheels and matte paint wrapped around the Freedom 106 V-twin.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/19/Paris_-_Salon_de_la_moto_2011_-_Victory_-_Vegas_Hight-Ball_-_001.jpg/1280px-Paris_-_Salon_de_la_moto_2011_-_Victory_-_Vegas_Hight-Ball_-_001.jpg"},{"name":"Big Dog Ridgeback","rarity":"common","id":"big-dog-ridgeback","subtitle":"American Cruisers","details":"The Big Dog Ridgeback was a rigid-frame production chopper from Wichita, built around a big S&S V-twin with a fat rear tire and stretched rails.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8f/Big-Dog-Ridgeback-Chopper_abstrakt.jpg/1280px-Big-Dog-Ridgeback-Chopper_abstrakt.jpg"},{"name":"BSA Bantam","rarity":"common","id":"bsa-bantam","subtitle":"British & European Classics","details":"Based on a German DKW design shared after the war, the two-stroke Bantam put generations of Britons on two wheels cheaply and cheerfully.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/57/1969_BSA_Bantam_%2816862472054%29.jpg/960px-1969_BSA_Bantam_%2816862472054%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Triumph Tiger Cub","rarity":"common","id":"triumph-tiger-cub","subtitle":"British & European Classics","details":"The 199cc Tiger Cub was a scaled-down Bonneville in spirit, a light overhead-valve single beloved by learners and trials riders.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f9/Triumph_Tiger_Cub_T20WD_%281966%29_-_18461845882.jpg/960px-Triumph_Tiger_Cub_T20WD_%281966%29_-_18461845882.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Royal Enfield Meteor 350","rarity":"common","id":"royal-enfield-meteor-350","subtitle":"British & European Classics","details":"Named for a 1950s Enfield tourer, the Meteor 350 cruises on a 349cc single with a counterbalancer for uncharacteristic smoothness.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e1/Royal_Enfield_Meteor_2021-3.jpg/960px-Royal_Enfield_Meteor_2021-3.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Ducati Scrambler","rarity":"common","id":"ducati-scrambler","subtitle":"British & European Classics","details":"Ducati's Scrambler revived a 1960s name for an air-cooled 803cc L-twin in a light, playful package with high bars and knobbly-tyre looks.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c1/2015_Ducati_Scrambler_Icon_right.JPG/960px-2015_Ducati_Scrambler_Icon_right.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Triumph Bonneville T100","rarity":"common","id":"triumph-bonneville-t100","subtitle":"British & European Classics","details":"The T100 carried the Bonneville name into Hinckley's modern era with a 790cc, later 865cc, air-cooled twin and authentic sixties detailing.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/59/Triumph_Bonneville_T100_%282011%29.jpg/960px-Triumph_Bonneville_T100_%282011%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Moto Guzzi V7 Stone","rarity":"common","id":"moto-guzzi-v7-stone","subtitle":"British & European Classics","details":"The V7 Stone keeps Guzzi's transverse twin naked and simple: a matt-painted tank, a single headlight and decades of Mandello character.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3d/Moto_Guzzi_V7_Stone_2022.jpg/960px-Moto_Guzzi_V7_Stone_2022.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"BMW R nineT","rarity":"common","id":"bmw-r-ninet","subtitle":"British & European Classics","details":"Built for BMW Motorrad's 90th anniversary, the R nineT mixed an air-oil-cooled 1170cc boxer with modular bodywork made for customisers.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3f/BMW_motorcycle_R-_nineT-5_-_July_2023_-_Sarah_Stierch.jpg/960px-BMW_motorcycle_R-_nineT-5_-_July_2023_-_Sarah_Stierch.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Triumph Trident 660","rarity":"common","id":"triumph-trident-660","subtitle":"British & European Classics","details":"The Trident name returned on a 660cc triple tuned for road-friendly midrange, packaged as Hinckley's accessible entry roadster.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cc/Triumph_Trident_660.jpg/960px-Triumph_Trident_660.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"BSA C15","rarity":"common","id":"bsa-c15","subtitle":"British & European Classics","details":"The unit-construction 249cc C15 replaced BSA's pre-unit singles in 1958 and became standard learner fare in schools and riding tests.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/30/BSA_C15_%281965%29_-_19650660828.jpg/960px-BSA_C15_%281965%29_-_19650660828.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Norton ES2","rarity":"common","id":"norton-es2","subtitle":"British & European Classics","details":"Norton's dependable 490cc single served riders for three decades, evolving from girder forks to the slimline featherbed in its final years.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b6/Norton_ES2_%281955%29_-_29515090286.jpg/960px-Norton_ES2_%281955%29_-_29515090286.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Velocette LE","rarity":"common","id":"velocette-le","subtitle":"British & European Classics","details":"The water-cooled, shaft-drive LE was so quiet and civilised that British police forces adopted it as their standard patrol mount.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7a/Hochgurgl-Top_Mountain_Motorcycle_Museum-Velocette_LE-1950-8PS-02ASD.jpg/960px-Hochgurgl-Top_Mountain_Motorcycle_Museum-Velocette_LE-1950-8PS-02ASD.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Sunbeam S8","rarity":"common","id":"sunbeam-s8","subtitle":"British & European Classics","details":"The S8 pared back the S7's specification with a slimmer front end, keeping the lengthwise twin and shaft drive of its luxury sibling.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fa/1950_Sunbeam_S8_motorcycle_%2831423387511%29.jpg/960px-1950_Sunbeam_S8_motorcycle_%2831423387511%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"AJS Model 16","rarity":"common","id":"ajs-model-16","subtitle":"British & European Classics","details":"The 347cc Model 16 was AMC's everyday single, a straightforward overhead-valve roadster sharing much with the Matchless G3.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2f/AJS_Model_16MS_1953.JPG/960px-AJS_Model_16MS_1953.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Matchless G3/L","rarity":"common","id":"matchless-g3l","subtitle":"British & European Classics","details":"The G3/L introduced Teledraulic forks to military service in 1941, and its 347cc single became a mainstay of post-war civilian riding.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/37/Matchless_G3L_350_%281941%29.jpg/960px-Matchless_G3L_350_%281941%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"BMW R27","rarity":"common","id":"bmw-r27","subtitle":"British & European Classics","details":"BMW's last single-cylinder shaft-drive model, the rubber-mounted 247cc R27 was engineered with a thoroughness far beyond its size.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/de/1964-BMW-R27.jpg/960px-1964-BMW-R27.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Triumph 3TA Twenty One","rarity":"common","id":"triumph-3ta-twenty-one","subtitle":"British & European Classics","details":"Named for its 21st year and cubic-inch displacement, the 3TA introduced Triumph's unit-construction 349cc twin in bathtub bodywork.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/2a/Triumph_3TA_%22Twenty_One%22_%281961%29.jpg/960px-Triumph_3TA_%22Twenty_One%22_%281961%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Royal Enfield Crusader","rarity":"common","id":"royal-enfield-crusader","subtitle":"British & European Classics","details":"The 248cc Crusader was Enfield's sporting lightweight, and its tuned Sports version was a favourite in production racing classes.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b5/Flickr_-_ronsaunders47_-_ROYAL_ENFIELD_CRUSADER._SINGLE_FOUR_STROKE_250_CC._1950s-1960s.jpg/960px-Flickr_-_ronsaunders47_-_ROYAL_ENFIELD_CRUSADER._SINGLE_FOUR_STROKE_250_CC._1950s-1960s.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Ducati 250 Mark 3","rarity":"common","id":"ducati-250-mark-3","subtitle":"British & European Classics","details":"Ducati's bevel-drive overhead-cam singles set standards for handling, and the 249cc Mark 3 was the sporting flagship of the range.","image":"https://upload.wikimedia.org/wikipedia/commons/3/32/Ducati_Mark3_250_02.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"},{"name":"Moto Guzzi Nuovo Falcone","rarity":"common","id":"moto-guzzi-nuovo-falcone","subtitle":"British & European Classics","details":"The horizontal-single Nuovo Falcone served Italian police and military riders for years, its exposed flywheel a Guzzi single signature.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0e/Moto_Guzzi_Nuovo_Falcone_-1.jpg/960px-Moto_Guzzi_Nuovo_Falcone_-1.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"BMW R60/2","rarity":"common","id":"bmw-r60-2","subtitle":"British & European Classics","details":"The Earles-fork R60/2 embodied BMW's sidecar-era touring ideal: a smooth 594cc boxer twin, shaft drive and legendary build quality.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/24/Granada_red_1967_BMW_R60-2.jpeg/960px-Granada_red_1967_BMW_R60-2.jpeg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Triumph Trophy TR5","rarity":"common","id":"triumph-trophy-tr5","subtitle":"British & European Classics","details":"The TR5 Trophy adapted Triumph's pre-unit 498cc twin for American desert racing, a high-pipe scrambler from the competition shop.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e4/1951_Triumph_TR5_Trophy_right_side.jpg/960px-1951_Triumph_TR5_Trophy_right_side.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"BSA B31","rarity":"common","id":"bsa-b31","subtitle":"British & European Classics","details":"The B31's 348cc single was BSA's post-war workhorse, a simple overhead-valve design that taught a generation to ride.","image":"https://upload.wikimedia.org/wikipedia/commons/d/d5/1949_BSA_B31_350cc-OHV_motorcycle_right_side.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled"},{"name":"Moto Guzzi V35","rarity":"common","id":"moto-guzzi-v35","subtitle":"British & European Classics","details":"The V35 shrank Guzzi's transverse V-twin to 346cc, yet kept shaft drive and linked brakes in a light machine aimed at younger riders.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9e/Moto_Guzzi_V35_II_%2814338451672%29.jpg/960px-Moto_Guzzi_V35_II_%2814338451672%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail"},{"name":"Honda CB750 Nighthawk","rarity":"common","id":"honda-cb750-nighthawk","subtitle":"Japanese Sport & Standards","details":"The CB750 Nighthawk revived a famous name with hydraulic valve adjusters and low upkeep, a do-everything standard of the 1990s.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/4f/Honda_CB750SC_Nighthawk_1982.JPG/1280px-Honda_CB750SC_Nighthawk_1982.JPG"},{"name":"Kawasaki KZ550","rarity":"common","id":"kawasaki-kz550","subtitle":"Japanese Sport & Standards","details":"The KZ550 was Kawasaki's nimble middleweight four, later gaining GPz styling and a reputation as a sweet, rev-happy commuter-sport bike.","image":"https://upload.wikimedia.org/wikipedia/commons/f/f8/1983_KZ550a4.jpg"},{"name":"Yamaha MT-07","rarity":"common","id":"yamaha-mt-07","subtitle":"Japanese Sport & Standards","details":"Yamaha's MT-07 used a torquey 689cc crossplane twin in a light naked chassis, a best-selling recipe for accessible, mischievous fun.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9c/2021_Black_Yamaha_MT-07.jpg/1280px-2021_Black_Yamaha_MT-07.jpg"},{"name":"Yamaha XS400","rarity":"common","id":"yamaha-xs400","subtitle":"Japanese Sport & Standards","details":"The XS400 twin gave Yamaha a frugal, friendly middleweight, its overhead-cam parallel twin serving commuters and new riders alike.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/94/Yamaha_XS-400.JPG/1280px-Yamaha_XS-400.JPG"},{"name":"Honda CB650","rarity":"common","id":"honda-cb650","subtitle":"Japanese Sport & Standards","details":"The 1979 CB650 replaced the CB550 with a new 627cc four, sitting between the CB400 and the mighty CB750 in Honda's standard range.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ea/Blue_Honda_CB650.jpg/1280px-Blue_Honda_CB650.jpg"},{"name":"Kawasaki Zephyr 750","rarity":"common","id":"kawasaki-zephyr-750","subtitle":"Japanese Sport & Standards","details":"Kawasaki's Zephyr 750 revived the air-cooled four's classic lines for the retro 1990s, echoing the original Z650 in steel and chrome.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e3/Kawasaki_Zephyr750_red.jpg/1280px-Kawasaki_Zephyr750_red.jpg"},{"name":"Suzuki Bandit 600","rarity":"common","id":"suzuki-bandit-600","subtitle":"Japanese Sport & Standards","details":"The Bandit 600 created the budget naked formula: an oil-cooled four in a simple steel frame, cheap, cheerful and endlessly modified.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/39/1996_Suzuki_GSF600_Bandit.JPG/1280px-1996_Suzuki_GSF600_Bandit.JPG"},{"name":"Yamaha XJ900","rarity":"common","id":"yamaha-xj900","subtitle":"Japanese Sport & Standards","details":"The XJ900 paired a torque-rich 891cc four with shaft drive and a sports-touring brief, Yamaha's gentleman express of the 1980s.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ec/Yamaha_XJ900%2C_blue.jpg/1280px-Yamaha_XJ900%2C_blue.jpg"},{"name":"Honda CB360","rarity":"common","id":"honda-cb360","subtitle":"Japanese Sport & Standards","details":"The CB360 succeeded the CB350 as Honda's workhorse twin, a 356cc six-speed standard built for commuting with a dash of style.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c2/1974_Honda_CB360_motorcycle.jpg/1280px-1974_Honda_CB360_motorcycle.jpg"},{"name":"Kawasaki KZ440","rarity":"common","id":"kawasaki-kz440","subtitle":"Japanese Sport & Standards","details":"The KZ440's belt-drive option and soft-tuned twin made it a gentle introduction to Kawasaki's Z range for 1980s commuters.","image":"https://upload.wikimedia.org/wikipedia/commons/0/05/Kawasaki_Z440_LTD.jpg"},{"name":"Suzuki GS450","rarity":"common","id":"suzuki-gs450","subtitle":"Japanese Sport & Standards","details":"The GS450 twin carried Suzuki's four-stroke range downward, a light 448cc standard popular with schools, couriers and new riders.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a6/Suzuki_GS_450.jpg/1280px-Suzuki_GS_450.jpg"},{"name":"Yamaha XJ550","rarity":"common","id":"yamaha-xj550","subtitle":"Japanese Sport & Standards","details":"The XJ550 combined a compact 528cc four with YICS intake swirl technology, a sporty middleweight sold in Maxim and Seca forms.","image":"https://upload.wikimedia.org/wikipedia/commons/a/a6/XJ550.jpg"},{"name":"Honda CB450","rarity":"common","id":"honda-cb450","subtitle":"Japanese Sport & Standards","details":"The CB450 'Black Bomber' was Honda's first big bike, a 444cc twin with torsion-bar valve springs that challenged British twins head-on.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/29/Paris_-_Bonhams_2016_-_Honda_CB_450_-_1966_-_002.jpg/1280px-Paris_-_Bonhams_2016_-_Honda_CB_450_-_1966_-_002.jpg"},{"name":"Kawasaki KZ400","rarity":"common","id":"kawasaki-kz400","subtitle":"Japanese Sport & Standards","details":"Kawasaki's KZ400 twin answered the fuel crises of the 1970s with economy and simplicity, a best-selling commuter across the Pacific.","image":"https://upload.wikimedia.org/wikipedia/commons/a/a9/Kawasaki_KZ400_Twin.jpg"},{"name":"Suzuki T500","rarity":"common","id":"suzuki-t500","subtitle":"Japanese Sport & Standards","details":"Suzuki's T500 Titan was the largest two-stroke twin of its day, a 492cc roadster fast enough to embarrass many four-stroke rivals.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/df/Suzuki_T500_-_1972_-_Mondial_de_l%27Automobile_de_Paris_2018_-_001.jpg/1280px-Suzuki_T500_-_1972_-_Mondial_de_l%27Automobile_de_Paris_2018_-_001.jpg"},{"name":"Yamaha RD250","rarity":"common","id":"yamaha-rd250","subtitle":"Japanese Sport & Standards","details":"The RD250 brought the RD350's two-stroke twin thrills in smaller form, a quarter-litre sporting twin with a devoted following in Britain and beyond.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/34/Yamaha_RD250.jpg/1280px-Yamaha_RD250.jpg"},{"name":"Honda CB175","rarity":"common","id":"honda-cb175","subtitle":"Japanese Sport & Standards","details":"The CB175's sloper twin revved eagerly and sipped fuel, a stylish small standard that brought Honda quality to the 175 class.","image":"https://upload.wikimedia.org/wikipedia/commons/0/02/CB175K42010HondaMotorcycleCB175.jpg"},{"name":"Kawasaki A1 Samurai","rarity":"common","id":"kawasaki-a1-samurai","subtitle":"Japanese Sport & Standards","details":"Kawasaki's A1 Samurai used rotary disc-valve induction on its 247cc twin, a quick small-bore sportster from the firm's early range.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9b/KAWASAKI_250AI_SAMURAI.JPG/1280px-KAWASAKI_250AI_SAMURAI.JPG"},{"name":"Suzuki GSX750F","rarity":"common","id":"suzuki-gsx750f","subtitle":"Japanese Sport & Standards","details":"The GSX750F, America's Katana 750, hid its sport-touring talents under full bodywork, powered by the durable oil-cooled GSX-R family four.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/48/Suzuki_GSX750F_01.jpg/1280px-Suzuki_GSX750F_01.jpg"},{"name":"Yamaha FZR600","rarity":"common","id":"yamaha-fzr600","subtitle":"Japanese Sport & Standards","details":"The FZR600 brought Genesis five-valve technology and a Deltabox frame to the middleweights, Yamaha's sharp 600 sportsbike of the 1990s.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0f/1991_Yamaha_FZR600.jpg/1280px-1991_Yamaha_FZR600.jpg"},{"name":"Honda VTR250","rarity":"common","id":"honda-vtr250","subtitle":"Japanese Sport & Standards","details":"Honda's VTR250 wore its V-twin in a trellis frame, a naked quarter-litre with big-bike looks and learner-friendly manners.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0c/HONDA_VTR250_2003_Pearl_Shining_Yellow.jpg/1280px-HONDA_VTR250_2003_Pearl_Shining_Yellow.jpg"},{"name":"Kawasaki Ninja 250R","rarity":"common","id":"kawasaki-ninja-250r","subtitle":"Japanese Sport & Standards","details":"The Ninja 250R proved small could be sporty, its 249cc twin and full fairing making it a long-running Kawasaki best-seller.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e9/Kawasaki_Ninja_250R_schwarz.jpg/1280px-Kawasaki_Ninja_250R_schwarz.jpg"},{"name":"Suzuki TU250X","rarity":"common","id":"suzuki-tu250x","subtitle":"Japanese Sport & Standards","details":"The TU250X kept the classic standard alive: air-cooled single, upright stance and retro styling with fuel injection underneath.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5d/2016_Suzuki_TU250X%2C_Upper_West_Side.jpg/1280px-2016_Suzuki_TU250X%2C_Upper_West_Side.jpg"},{"name":"Yamaha SR250","rarity":"common","id":"yamaha-sr250","subtitle":"Japanese Sport & Standards","details":"Yamaha's SR250 shrank the SR single formula to 249cc, an easygoing custom-styled commuter that shared the big SR's simple charm.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f7/1980_Yamaha_SR250.jpg/1280px-1980_Yamaha_SR250.jpg"},{"name":"Honda CBR250R","rarity":"common","id":"honda-cbr250r","subtitle":"Japanese Sport & Standards","details":"Honda's 2011 CBR250R brought single-cylinder economy to the CBR family, a light sports standard styled after the VFR1200F.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/db/Red_2011_Honda_CBR250R_Chiang_Mai%2C_Thailand.jpg/1280px-Red_2011_Honda_CBR250R_Chiang_Mai%2C_Thailand.jpg"},{"name":"Honda CB400 Super Four","rarity":"common","id":"honda-cb400-super-four","subtitle":"Japanese Sport & Standards","details":"The CB400 Super Four is a Japan-market staple, a 399cc four that gained VTEC valve timing and a loyal home following.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/05/Honda_CB400_SUPER_FOUR_HYPER_VTEC_Revo.JPG/1280px-Honda_CB400_SUPER_FOUR_HYPER_VTEC_Revo.JPG"},{"name":"Honda CRF250R","rarity":"common","id":"honda-crf250r","subtitle":"Dirt, Adventure & Off-Road","details":"Honda's quarter-litre motocrosser, the CRF250R brought four-stroke power to the 125 class with a high-revving 249cc single-cylinder engine.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/30/2010_Honda_CRF250R_at_the_2009_Seattle_International_Motorcycle_Show_1.jpg/1280px-2010_Honda_CRF250R_at_the_2009_Seattle_International_Motorcycle_Show_1.jpg"},{"name":"Honda CRF450R","rarity":"common","id":"honda-crf450r","subtitle":"Dirt, Adventure & Off-Road","details":"The CRF450R is Honda's flagship motocrosser, a 449cc four-stroke single that has been a fixture of AMA supercross and motocross start gates.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/85/2010_Honda_CRF450R_at_the_2009_Seattle_International_Motorcycle_Show_2.jpg/1280px-2010_Honda_CRF450R_at_the_2009_Seattle_International_Motorcycle_Show_2.jpg"},{"name":"Honda CR250R","rarity":"common","id":"honda-cr250r","subtitle":"Dirt, Adventure & Off-Road","details":"Honda's CR250R was a benchmark 249cc two-stroke motocrosser, a championship-winning machine from the final great era of 250cc two-strokes.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/83/Honda_1997_CR250R_in_the_Honda_Collection_Hall.JPG/1280px-Honda_1997_CR250R_in_the_Honda_Collection_Hall.JPG"},{"name":"Honda XR250R","rarity":"common","id":"honda-xr250r","subtitle":"Dirt, Adventure & Off-Road","details":"The XR250R was Honda's friendly air-cooled 249cc trail bike, a four-valve single known for reliability on enduro loops and green lanes.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c6/1994_Honda_XR250R.jpg/1280px-1994_Honda_XR250R.jpg"},{"name":"Honda XR600R","rarity":"common","id":"honda-xr600r","subtitle":"Dirt, Adventure & Off-Road","details":"Honda's XR600R was a big air-cooled trail thumper, a 591cc single that was a dominant force in Baja-style desert racing for many years.","image":"https://upload.wikimedia.org/wikipedia/commons/2/2a/Hondaxr6001993.jpg"},{"name":"Yamaha YZ250","rarity":"common","id":"yamaha-yz250","subtitle":"Dirt, Adventure & Off-Road","details":"Yamaha's YZ250 is a long-running 249cc two-stroke motocrosser, kept in production long after rivals switched entirely to four-stroke machines.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7b/YZ250.jpg/1280px-YZ250.jpg"},{"name":"Yamaha YZ450F","rarity":"common","id":"yamaha-yz450f","subtitle":"Dirt, Adventure & Off-Road","details":"The YZ450F is Yamaha's flagship four-stroke motocrosser, famous for its reversed, slanted cylinder layout that centralizes mass around the rider.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/da/YAMAHA_YZ450F_2010-1_Yamaha_Communication_Plaza.jpg/1280px-YAMAHA_YZ450F_2010-1_Yamaha_Communication_Plaza.jpg"},{"name":"Yamaha YZ125","rarity":"common","id":"yamaha-yz125","subtitle":"Dirt, Adventure & Off-Road","details":"Yamaha's YZ125 is a light, high-revving 125cc two-stroke motocrosser, a beloved training ground for generations of young racers.","image":"https://upload.wikimedia.org/wikipedia/commons/7/7f/Yamaha_YZ125_Motorcycle.jpg"},{"name":"Yamaha WR450F","rarity":"common","id":"yamaha-wr450f","subtitle":"Dirt, Adventure & Off-Road","details":"The WR450F is Yamaha's enduro version of the YZ450F, with a wide-ratio gearbox, lights and softer settings for trails and cross-country racing.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8a/2010_Yamaha_WR450F_at_2009_Seattle_International_Motorcycle_Show_1.jpg/1280px-2010_Yamaha_WR450F_at_2009_Seattle_International_Motorcycle_Show_1.jpg"},{"name":"Yamaha DT125R","rarity":"common","id":"yamaha-dt125r","subtitle":"Dirt, Adventure & Off-Road","details":"Yamaha's DT125R was a 125cc two-stroke trail bike and learner favorite, part of the DT line that introduced many riders to off-road motorcycling.","image":"https://upload.wikimedia.org/wikipedia/commons/5/57/Yamaha_DT125_R_4bl_1998.jpg"},{"name":"Suzuki RM-Z450","rarity":"common","id":"suzuki-rm-z450","subtitle":"Dirt, Adventure & Off-Road","details":"Suzuki's RM-Z450 is its flagship 449cc four-stroke motocrosser, a sharp-cornering machine with a long AMA racing heritage.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/99/Suzuki_RM-Z450_-_EICMA_2024.jpg/1280px-Suzuki_RM-Z450_-_EICMA_2024.jpg"},{"name":"Suzuki RM125","rarity":"common","id":"suzuki-rm125","subtitle":"Dirt, Adventure & Off-Road","details":"The RM125 was Suzuki's 125cc two-stroke motocrosser, raced for decades in the lightest MX class before four-strokes reshaped the sport.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/e4/Suzuki_RM125V.jpg/1280px-Suzuki_RM125V.jpg"},{"name":"Kawasaki KX450","rarity":"common","id":"kawasaki-kx450","subtitle":"Dirt, Adventure & Off-Road","details":"Kawasaki's KX450 is Team Green's flagship four-stroke motocrosser, a 449cc machine with a long record in AMA supercross and motocross.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/e/ee/Kawasaki_KX450_2.jpeg/1280px-Kawasaki_KX450_2.jpeg"},{"name":"Kawasaki KX125","rarity":"common","id":"kawasaki-kx125","subtitle":"Dirt, Adventure & Off-Road","details":"This 1975 KX125 is an early Kawasaki motocrosser, from the first years when the KX line took on the dominant Japanese and European MX brands.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/72/1975_Kawasaki_KX125_%40_National_Motor_Museum%2C_Birdwood_20250109-121512.jpg/1280px-1975_Kawasaki_KX125_%40_National_Motor_Museum%2C_Birdwood_20250109-121512.jpg"},{"name":"KTM 300 EXC","rarity":"common","id":"ktm-300-exc","subtitle":"Dirt, Adventure & Off-Road","details":"KTM's 300 EXC is a 293cc two-stroke enduro legend, prized for trials-like low-end torque in a light chassis built for hard enduro and woods riding.","image":"https://upload.wikimedia.org/wikipedia/commons/c/cd/Oskar-kaczmarczyk-sklep-ktm-ktmsklep.pl-team-enduro-ktm-300-exc-tpi_%285%29.jpg"},{"name":"KTM 350 EXC-F","rarity":"common","id":"ktm-350-exc-f","subtitle":"Dirt, Adventure & Off-Road","details":"The 350 EXC-F is KTM's mid-size four-stroke enduro, a 349cc single blending 250-like agility with near-450 torque for woods and cross-country racing.","image":"https://upload.wikimedia.org/wikipedia/commons/4/42/KTM_350_EXC-F.JPG"},{"name":"KTM 125 SX","rarity":"common","id":"ktm-125-sx","subtitle":"Dirt, Adventure & Off-Road","details":"KTM's 125 SX is a full-size 125cc two-stroke motocrosser, the traditional stepping stone from minibikes up to the senior MX classes.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5a/Ktm_125sx_2019.jpg/1280px-Ktm_125sx_2019.jpg"},{"name":"KTM 250 SX-F","rarity":"common","id":"ktm-250-sx-f","subtitle":"Dirt, Adventure & Off-Road","details":"The 250 SX-F is KTM's four-stroke quarter-litre motocrosser, a high-revving 250 that has won titles in AMA and world championship racing.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0b/KTM_250_SX-F_-_Mondial_de_l%27Automobile_de_Paris_2018_-_001.jpg/1280px-KTM_250_SX-F_-_Mondial_de_l%27Automobile_de_Paris_2018_-_001.jpg"},{"name":"KTM 450 SX-F","rarity":"common","id":"ktm-450-sx-f","subtitle":"Dirt, Adventure & Off-Road","details":"KTM's 450 SX-F is the Austrian firm's flagship motocrosser, the platform behind multiple AMA Supercross championships in the 450 class.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/92/KTM_SX-F_450_-_Dungey.jpg/1280px-KTM_SX-F_450_-_Dungey.jpg"},{"name":"Bultaco Sherpa T","rarity":"common","id":"bultaco-sherpa-t","subtitle":"Dirt, Adventure & Off-Road","details":"Bultaco's Sherpa T was the trials bike that changed the sport in the 1960s, developed with Sammy Miller and winning titles on two-stroke power.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/26/Bultaco_350_Sherpa_T.jpg/1280px-Bultaco_350_Sherpa_T.jpg"},{"name":"Montesa Cota 4RT","rarity":"common","id":"montesa-cota-4rt","subtitle":"Dirt, Adventure & Off-Road","details":"Montesa's Cota 4RT is a four-stroke trials machine built in Spain with Honda power, long associated with world champion Toni Bou.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a6/Montesa_Cota_4RT.jpg/1280px-Montesa_Cota_4RT.jpg"},{"name":"Maico MC 490","rarity":"common","id":"maico-mc-490","subtitle":"Dirt, Adventure & Off-Road","details":"The 1981 Maico MC 490 is remembered as one of the great open-class two-stroke motocrossers, a 488cc single with huge, tractable power.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/45/Maico_MC_490_1981.jpg/1280px-Maico_MC_490_1981.jpg"},{"name":"Honda CT110 Hunter Cub","rarity":"common","id":"honda-ct110-hunter-cub","subtitle":"Dirt, Adventure & Off-Road","details":"Australia's beloved postie bike, the CT110 Hunter Cub is a 105cc step-through trail machine built for mail rounds, farms and outback tracks.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7c/Honda_TRAIL110_CT110_Hunter_Cub.jpg/1280px-Honda_TRAIL110_CT110_Hunter_Cub.jpg"},{"name":"Yamaha AG200","rarity":"common","id":"yamaha-ag200","subtitle":"Dirt, Adventure & Off-Road","details":"Yamaha's AG200 is a purpose-built farm bike: a 196cc air-cooled single with a sealed chain case, dual stands and racks for agricultural work.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/05/Yamaha_AG_200_2017_model.jpg/1280px-Yamaha_AG_200_2017_model.jpg"},{"name":"Yamaha Vino 125","rarity":"common","id":"yamaha-vino-125","subtitle":"Scooters, Minis & Oddballs","details":"Yamaha's Vino 125 dresses a practical step-through in retro curves, powered by a simple air-cooled 125cc single with storage under the seat.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/44/Yamaha_Vino_125_2006.jpg/960px-Yamaha_Vino_125_2006.jpg"},{"name":"Honda Metropolitan","rarity":"common","id":"honda-metropolitan","subtitle":"Scooters, Minis & Oddballs","details":"Honda's Metropolitan is a 49cc retro step-through built for campus and city hops, sipping fuel through an easy automatic transmission.","image":"https://upload.wikimedia.org/wikipedia/commons/4/4a/2005_Honda_Metropolitan_Kiwi.jpg"},{"name":"Vespa Sprint 125","rarity":"common","id":"vespa-sprint-125","subtitle":"Scooters, Minis & Oddballs","details":"Vespa's Sprint pairs the small modern Vespa body with 12-inch wheels and a rectangular headlight, named for the sporting Sprints of the 1960s.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/53/Piaggio_Vespa_Sprint_125.jpg/960px-Piaggio_Vespa_Sprint_125.jpg"},{"name":"Vespa LX 150","rarity":"common","id":"vespa-lx-150","subtitle":"Scooters, Minis & Oddballs","details":"The LX 150 carried Vespa into the four-stroke era with a steel monocoque body, a 150cc-class single and the classic round headlight.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/7/72/Vespa_LX_150.jpg/960px-Vespa_LX_150.jpg"},{"name":"Suzuki Burgman 400","rarity":"common","id":"suzuki-burgman-400","subtitle":"Scooters, Minis & Oddballs","details":"Suzuki's Burgman 400 brings maxi-scooter touring comfort down a size, with a 399cc single, a big stepped seat and generous underseat storage.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/07/Suzuki_Burgman_400.JPG/960px-Suzuki_Burgman_400.JPG"},{"name":"Yamaha XMAX","rarity":"common","id":"yamaha-xmax","subtitle":"Scooters, Minis & Oddballs","details":"Yamaha's XMAX is a sporty maxi-scooter with motorcycle-style forks and a punchy single, built for highway commuting in step-through ease.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/60/Yamaha_Xmax.jpg/960px-Yamaha_Xmax.jpg"},{"name":"Honda Ape 50","rarity":"common","id":"honda-ape-50","subtitle":"Scooters, Minis & Oddballs","details":"Honda's Ape mini uses a vertical 49cc single in a proper motorcycle frame, giving monkey-bike proportions with big-bike controls.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/5/5d/Honda_Ape_50cc.JPG/960px-Honda_Ape_50cc.JPG"},{"name":"Honda Navi","rarity":"common","id":"honda-navi","subtitle":"Scooters, Minis & Oddballs","details":"Honda's Navi blurs scooter and minibike: a 109cc automatic drivetrain in motorcycle clothes, with a storage box where a fuel tank would sit.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/2/24/Honda_Navi_100.jpg/960px-Honda_Navi_100.jpg"},{"name":"Piaggio Liberty 125","rarity":"common","id":"piaggio-liberty-125","subtitle":"Scooters, Minis & Oddballs","details":"Piaggio's Liberty rolls on tall wheels for stability over rough city streets, pairing a slim step-through body with an air-cooled 125cc single.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c5/Piaggio_Liberty_125_%28Salerno%29.jpg/960px-Piaggio_Liberty_125_%28Salerno%29.jpg"},{"name":"Aprilia Scarabeo","rarity":"common","id":"aprilia-scarabeo","subtitle":"Scooters, Minis & Oddballs","details":"Aprilia's Scarabeo mixes scooter ease with big 16-inch wheels and Italian styling, taking its name from the Italian word for a scarab beetle.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/9/96/Aprilia_Scarabeo_150i.jpg/960px-Aprilia_Scarabeo_150i.jpg"},{"name":"Honda Forza 300","rarity":"common","id":"honda-forza-300","subtitle":"Scooters, Minis & Oddballs","details":"Honda's Forza 300 is a GT scooter with an electrically adjustable windscreen, a smooth 279cc single and room for two helmets under the seat.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/b/b1/Honda_Forza_300_ABS.jpg/960px-Honda_Forza_300_ABS.jpg"},{"name":"BMW C 650 GT","rarity":"common","id":"bmw-c-650-gt","subtitle":"Scooters, Minis & Oddballs","details":"BMW's C 650 GT maxi-scooter uses a 647cc twin behind a touring fairing, bringing BMW grand-touring comfort to a step-through machine.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/82/BMW_C_650_GT%2C_left_view.jpg/960px-BMW_C_650_GT%2C_left_view.jpg"},{"name":"Vespa ET4","rarity":"common","id":"vespa-et4","subtitle":"Scooters, Minis & Oddballs","details":"The ET4 rebooted Vespa for the modern era, adding a four-stroke engine, an automatic gearbox and steel bodywork in the classic mold.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/0/00/Piaggio_Vespa_ET4.jpg/960px-Piaggio_Vespa_ET4.jpg"},{"name":"Yamaha NMAX 155","rarity":"common","id":"yamaha-nmax-155","subtitle":"Scooters, Minis & Oddballs","details":"Yamaha's NMAX 155 uses variable valve actuation on its 155cc single, giving the compact maxi-scooter stronger pull for highway commuting.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/6/63/2025_Yamaha_NMAX_155_Standard.jpg/960px-2025_Yamaha_NMAX_155_Standard.jpg"},{"name":"Piaggio Beverly 250","rarity":"common","id":"piaggio-beverly-250","subtitle":"Scooters, Minis & Oddballs","details":"Piaggio's Beverly is a big-wheel city scooter with a 250cc-class single, mixing slim Italian styling with stable, motorcycle-like road manners.","image":"https://upload.wikimedia.org/wikipedia/commons/a/a6/Piaggio_Beverly_250.jpg"},{"name":"Kymco Agility 125","rarity":"common","id":"kymco-agility-125","subtitle":"Scooters, Minis & Oddballs","details":"Kymco's Agility 125 is a no-nonsense city scooter from Taiwan, built around a simple air-cooled 125 with tall wheels and low running costs.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/8a/Kymco_Agility_125_R16%2B.jpg/960px-Kymco_Agility_125_R16%2B.jpg"},{"name":"Gilera Runner 125","rarity":"common","id":"gilera-runner-125","subtitle":"Scooters, Minis & Oddballs","details":"The original Gilera Runner 125 brought scooter-racing style to the street with a liquid-cooled two-stroke and a motorcycle-style frame spine.","image":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/49/Gilera_Runner_125_SP.jpg/960px-Gilera_Runner_125_SP.jpg"},{"name":"GoldenEye Cagiva 600 W16","rarity":"common","id":"goldeneye-cagiva-w16","subtitle":"Famous & Movie Bikes","details":"A military Cagiva 600 W16 thunders through the St Petersburg tank chase era of GoldenEye, part of Bond's 1995 return to the big screen.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/12/Cagiva_600_W16_%28GoldenEye%29_left_National_Motor_Museum%2C_Beaulieu.jpg/1280px-Cagiva_600_W16_%28GoldenEye%29_left_National_Motor_Museum%2C_Beaulieu.jpg"},{"name":"Quantum of Solace Montesa Cota 4RT","rarity":"common","id":"quantum-of-solace-montesa-cota","subtitle":"Famous & Movie Bikes","details":"Bond steals a Montesa Cota 4RT trials bike for the rooftop escape in Quantum of Solace, hopping across Siena's tiles after the Palio.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/ff/Montesa_Cota_4RT_%28Quantum_of_Solace%29_National_Motor_Museum%2C_Beaulieu.jpg/1280px-Montesa_Cota_4RT_%28Quantum_of_Solace%29_National_Motor_Museum%2C_Beaulieu.jpg"},{"name":"Ghost Rider Hell Cycle","rarity":"common","id":"ghost-rider-hell-cycle","subtitle":"Famous & Movie Bikes","details":"When Johnny Blaze transforms in Ghost Rider, his bike becomes the Hell Cycle, a skeletal, chain-forked machine wreathed in hellfire.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/07/Ghost_rider_bike.JPG/1280px-Ghost_rider_bike.JPG"},{"name":"Orange County Choppers Fire Bike","rarity":"common","id":"orange-county-choppers-fire-bike","subtitle":"Famous & Movie Bikes","details":"Orange County Choppers built the Fire Bike as a tribute to the firefighters of 9/11 on American Chopper, complete with a piece of World Trade Center steel.","image":"https://upload.wikimedia.org/wikipedia/commons/f/f3/FireBike.jpg"},{"name":"Steve McQueen's 1931 Panther","rarity":"common","id":"steve-mcqueen-1931-panther","subtitle":"Famous & Movie Bikes","details":"Steve McQueen owned this 1931 Panther and sidecar, a thumping British single from the collection of motorcycling's most famous film star.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/80/1931_Panther_motorcycle_once_owned_by_actor_Steve_McQueen_by_Don_Ramey_Logan.jpg/1280px-1931_Panther_motorcycle_once_owned_by_actor_Steve_McQueen_by_Don_Ramey_Logan.jpg"},{"name":"Che Guevara's La Poderosa II","rarity":"common","id":"la-poderosa-ii-norton","subtitle":"Famous & Movie Bikes","details":"Ernesto 'Che' Guevara crossed South America on a 1939 Norton 500 named La Poderosa II, the journey retold in The Motorcycle Diaries book and film.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/66/La_Poderosa_Museo_Che_Guevara.jpg/1280px-La_Poderosa_Museo_Che_Guevara.jpg"},{"name":"Roman Holiday Vespa","rarity":"common","id":"roman-holiday-vespa","subtitle":"Famous & Movie Bikes","details":"Audrey Hepburn and Gregory Peck tour Rome on a Vespa in Roman Holiday, the 1953 romance that made the little scooter a worldwide style icon.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/65/Audrey_Hepburn_and_Gregory_Peck_on_Vespa_in_Roman_Holiday_trailer.jpg/1280px-Audrey_Hepburn_and_Gregory_Peck_on_Vespa_in_Roman_Holiday_trailer.jpg"},{"name":"Un Americano a Roma Harley WLA","rarity":"common","id":"un-americano-a-roma-harley-wla","subtitle":"Famous & Movie Bikes","details":"Alberto Sordi rides this 1942 Harley-Davidson WLA in Un americano a Roma, the beloved 1954 Italian comedy, and the original bike still survives.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/df/Da_I_Vitelloni_Club_Alberto_Sordi%2C_Harley_Davidson_750cc_WLA_del_1942%2C_moto_originale_usata_nelle_scene_del_film_Un_americano_a_Roma%2C_della_Collezione_Stefano_Saliola.jpg/1280px-thumbnail.jpg"},{"name":"Carl Fogarty's Honda Race Bike","rarity":"common","id":"carl-fogarty-honda-race-bike","subtitle":"Famous & Movie Bikes","details":"Carl Fogarty, four-time World Superbike champion, raced Hondas like this RC-series superbike in his late-nineties campaigns for Honda Britain.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/58/Carl_Fogarty%27s_bike%2C_Winfields%2C_Haslingden.jpg/1280px-Carl_Fogarty%27s_bike%2C_Winfields%2C_Haslingden.jpg"},{"name":"Barry Sheene's Suzuki RG500","rarity":"common","id":"barry-sheene-suzuki-rg500","subtitle":"Famous & Movie Bikes","details":"Barry Sheene's Texaco Heron Suzuki RG500, number 7, carried Britain's favourite racer to Grand Prix glory in the late seventies golden age.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/6e/Barry_Sheene%27s_1979_Suzuki_RG500_XR27_%2849255120377%29.jpg/1280px-Barry_Sheene%27s_1979_Suzuki_RG500_XR27_%2849255120377%29.jpg"},{"name":"Mike Hailwood's TT-Winning Ducati","rarity":"common","id":"mike-hailwood-ducati-tt","subtitle":"Famous & Movie Bikes","details":"Mike Hailwood's Ducati 900 NCR won the 1978 Isle of Man TT Formula One race, the fairytale comeback that sealed his legend as 'Mike the Bike'.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/02/1978_Mike_Hailwood_race_winning_bike_IOMTT_and_Mallory_Park_%28Museo_Ducati%29.jpg/1280px-1978_Mike_Hailwood_race_winning_bike_IOMTT_and_Mallory_Park_%28Museo_Ducati%29.jpg"},{"name":"Top Gear Vietnam Vespa","rarity":"common","id":"top-gear-vietnam-vespa","subtitle":"Famous & Movie Bikes","details":"Jeremy Clarkson's battered green Vespa carried him the length of Vietnam in the Top Gear Vietnam Special, against every odd the presenters could invent.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f1/Piaggio_Vespa_scooter_-_Top_Gear_%285963858188%29.jpg/1280px-Piaggio_Vespa_scooter_-_Top_Gear_%285963858188%29.jpg"},{"name":"Top Gear's Honda Chaly Backup Bike","rarity":"common","id":"top-gear-honda-chaly-backup-bike","subtitle":"Famous & Movie Bikes","details":"The dreaded Honda Chaly backup bike, painted as the American flag, haunted the Top Gear presenters through Vietnam: break down, and you rode this.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/4/46/Honda_Chaly_CF_70_backup_motorcycle_-_Top_Gear_%285963846328%29.jpg/1280px-Honda_Chaly_CF_70_backup_motorcycle_-_Top_Gear_%285963846328%29.jpg"},{"name":"James May's Meccano Motorcycle","rarity":"common","id":"james-may-meccano-motorcycle","subtitle":"Famous & Movie Bikes","details":"James May's Toy Stories built a full-size, rideable motorcycle and sidecar entirely from Meccano, then rode it around the Isle of Man TT course.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c7/Meccano_Motorcycle_made_for_James_May%27s_Toy_Stories.JPG/1280px-Meccano_Motorcycle_made_for_James_May%27s_Toy_Stories.JPG"},{"name":"No Time To Die Triumph Scrambler 1200","rarity":"common","id":"no-time-to-die-triumph-scrambler","subtitle":"Famous & Movie Bikes","details":"Bond's blacked-out Triumph Scrambler 1200 XE storms through Matera in No Time To Die, jumping a wall into a piazza in one impossible leap.","image":"https://www.visordown.com/sites/default/files/3%20Triumph%20Scrambler%201200%20XE%20as%20used%20in%20No%20time%20To%20Die.jpg?width=1600"},{"name":"Dragon Tattoo Honda CB350","rarity":"common","id":"dragon-tattoo-honda-cb350","subtitle":"Famous & Movie Bikes","details":"Lisbeth Salander rides a black Honda CB350 scrambler in The Girl with the Dragon Tattoo, one of three identical bikes Glory Motorworks built for the film.","image":"https://images.bikeexif.com/2011/12/motorcycle-movie.jpg"},{"name":"Skyfall Turkish Police Honda","rarity":"common","id":"skyfall-turkish-police-honda","subtitle":"Famous & Movie Bikes","details":"Turkish traffic police Hondas chase Bond across Istanbul's rooftops in Skyfall, their white CRF250s leaping market stalls in the opening pursuit.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/92/Skyfall_-_Honda_CRF250R_%28Turkish_Police%29.jpg/1280px-Skyfall_-_Honda_CRF250R_%28Turkish_Police%29.jpg"},{"name":"Ghost Rider Stunt Bike","rarity":"common","id":"ghost-rider-stunt-bike","subtitle":"Famous & Movie Bikes","details":"Johnny Blaze's flame-painted stunt bike headlines his stadium shows in Ghost Rider, before hellfire turns his ride into something far worse.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/d/db/Ghost_Rider_motorcycle.jpg/1280px-Ghost_Rider_motorcycle.jpg"},{"name":"Indian Prince","rarity":"common","id":"indian-prince","subtitle":"Historic Pioneers","details":"The Prince was Indian's lightweight 350cc single of 1925, a girder-forked machine aimed at younger riders and overseas markets.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/a/a3/Indian_Prince_350cc_1925.jpg/1280px-Indian_Prince_350cc_1925.jpg"},{"name":"DKW SS 250","rarity":"common","id":"dkw-ss-250","subtitle":"Historic Pioneers","details":"The SS 250 was DKW's split-single two-stroke sports model of the late 1930s, from what was then the world's largest motorcycle maker.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/15/DKW_SS_250_-_Seite.jpg/1280px-DKW_SS_250_-_Seite.jpg"},{"name":"Reading Standard Model A","rarity":"common","id":"reading-standard-model-a","subtitle":"Historic Pioneers","details":"Reading Standard of Pennsylvania built this 400cc single in 1908; the firm later became known for tough V-twins and hillclimb racers.","image":"https://upload.wikimedia.org/wikipedia/commons/8/8a/Reading_Standard_Model_A_400_cc_1908.jpg"},{"name":"Excelsior Auto-Cycle","rarity":"common","id":"excelsior-auto-cycle","subtitle":"Historic Pioneers","details":"Chicago's Excelsior Auto-Cycle grew from light singles into big V-twins like this 1,000cc machine of 1918, built under Schwinn ownership.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fb/Excelsior_Auto_Cycle_%2823941836077%29.jpg/1280px-Excelsior_Auto_Cycle_%2823941836077%29.jpg"},{"name":"Cleveland Lightweight","rarity":"common","id":"cleveland-lightweight","subtitle":"Historic Pioneers","details":"Nicknamed the 'Postman Motorcycle', Cleveland's 269cc two-stroke lightweight was a cheap, simple commuter built in Ohio from 1915.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/0/0f/Cleveland_269cc_1919_Aka_Postman_Motorcycle.jpg/1280px-Cleveland_269cc_1919_Aka_Postman_Motorcycle.jpg"},{"name":"Werner Motocyclette","rarity":"common","id":"werner-motocyclette","subtitle":"Historic Pioneers","details":"The Paris-built Werner Motocyclette put its engine low in the frame from 1901, a layout that set the pattern for the modern motorcycle.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/33/R%C3%A9tromobile_2017_-_Werner_motocyclette_%C3%A0_deux_cylindres_-_1906_-_001.jpg/1280px-R%C3%A9tromobile_2017_-_Werner_motocyclette_%C3%A0_deux_cylindres_-_1906_-_001.jpg"},{"name":"Michaux-Perreaux Steam Velocipede","rarity":"common","id":"michaux-perreaux-steam-velocipede","subtitle":"Historic Pioneers","details":"This Paris-built steam velocipede of the late 1860s mounted a small steam engine beneath a bicycle frame, among the earliest powered two-wheelers.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/16/Michaux-Perreaux_steam_velocip%C3%A8de.jpg/1280px-Michaux-Perreaux_steam_velocip%C3%A8de.jpg"},{"name":"De Dion-Bouton Tricycle","rarity":"common","id":"de-dion-bouton-tricycle","subtitle":"Historic Pioneers","details":"De Dion-Bouton's light petrol tricycle was among the best-selling motor vehicles of the 1890s, and its engine was copied across Europe.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f1/1900_De_Dion-Bouton_Tricycle.JPG/1280px-1900_De_Dion-Bouton_Tricycle.JPG"},{"name":"Levis Popular","rarity":"common","id":"levis-popular","subtitle":"Historic Pioneers","details":"The Levis Popular ran a 211cc two-stroke single built in Birmingham; Levis two-strokes were famed for economy and trials success.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/28/Levis_Popular_Cassington.jpg/1280px-Levis_Popular_Cassington.jpg"},{"name":"Terrot OSC 250","rarity":"common","id":"terrot-osc-250","subtitle":"Historic Pioneers","details":"Dijon's Terrot was France's largest motorcycle maker between the wars; the OSC paired a 250cc single with a compact, sporting chassis.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/9/9b/Hochgurgl-Top_Mountain_Motorcycle_Museum-Terrot_OSC_250-1930-247ccm-01ASD.jpg/1280px-Hochgurgl-Top_Mountain_Motorcycle_Museum-Terrot_OSC_250-1930-247ccm-01ASD.jpg"},{"name":"Saroléa Model 25","rarity":"common","id":"sarolea-model-25","subtitle":"Historic Pioneers","details":"Belgium's Sarolea, building motorcycles since 1900, offered the Model 25 as a 350cc single - a refined Herstal machine of the late 1920s.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/6/60/Hochgurgl-Top_Mountain_Motorcycle_Museum-Sarolea-1927-350ccm-01ASD.jpg/1280px-Hochgurgl-Top_Mountain_Motorcycle_Museum-Sarolea-1927-350ccm-01ASD.jpg"},{"name":"Peugeot P110","rarity":"common","id":"peugeot-p110","subtitle":"Historic Pioneers","details":"The P110 carried Peugeot's motorcycle line into 1930, a French single-cylinder machine from one of the world's oldest motor firms.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/8/8d/Peugeot_P110_1930.jpg/1280px-Peugeot_P110_1930.jpg"},{"name":"FN M70","rarity":"common","id":"fn-m70","subtitle":"Historic Pioneers","details":"FN's M70 single, built at Herstal from 1927 to 1936, was a rugged 348cc Belgian tourer from the great Herstal arms and motor works.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3d/Hochgurgl-Top_Mountain_Motorcycle_Museum-FN_Herstal-1932-348ccm-01ASD.jpg/1280px-Hochgurgl-Top_Mountain_Motorcycle_Museum-FN_Herstal-1932-348ccm-01ASD.jpg"},{"name":"Motosacoche MAG 850","rarity":"common","id":"motosacoche-mag-850","subtitle":"Historic Pioneers","details":"Geneva's Motosacoche supplied MAG engines to many makers; this 850cc V-twin three-speeder, shown with its sidecar, is its own complete machine.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/5/5d/Hochgurgl-Top_Mountain_Motorcycle_Museum-Motosacoche_MAG-850ccm-01ESD.jpg/1280px-Hochgurgl-Top_Mountain_Motorcycle_Museum-Motosacoche_MAG-850ccm-01ESD.jpg"},{"name":"Gillet Herstal Tour du Monde","rarity":"common","id":"gillet-herstal-tour-du-monde","subtitle":"Historic Pioneers","details":"This 350cc Gillet Herstal was built for a publicity ride around the world in 1927, a Belgian single made for distance over bad roads.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1d/1927_Gillet_Herstal%2C_Tour_du_monde%2C_350cm3%2C_Mus%C3%A9e_de_la_Moto_et_du_V%C3%A9lo%2C_Amneville%2C_France.JPG/1280px-1927_Gillet_Herstal%2C_Tour_du_monde%2C_350cm3%2C_Mus%C3%A9e_de_la_Moto_et_du_V%C3%A9lo%2C_Amneville%2C_France.JPG"},{"name":"Sunbeam Model 8","rarity":"common","id":"sunbeam-model-8","subtitle":"Historic Pioneers","details":"The Model 8 was Sunbeam's 350cc overhead-valve single, a smaller sibling to the Model 90 finished in black enamel with gold lining.","image":"https://upload.wikimedia.org/wikipedia/commons/9/97/Sunbeam_Model_8_350_cc_1928.jpg"},{"name":"Velocette KTT","rarity":"common","id":"velocette-ktt","subtitle":"Historic Pioneers","details":"The KTT was Velocette's over-the-counter TT racer, a 350cc overhead-cam single that privateers rode at the Isle of Man from 1929.","image":"https://thumb.wikimedia.org/wikipedia/commons/thumb/2/24/Velocette_KTT_Mk8%2C_350_cm%C2%B3%2C_Bj._1939.jpg/1280px-Velocette_KTT_Mk8%2C_350_cm%C2%B3%2C_Bj._1939.jpg"},{"name":"BSA Sloper","rarity":"common","id":"bsa-sloper","subtitle":"Historic Pioneers","details":"BSA's Sloper took its name from its inclined 500cc engine, a quiet, elegant Birmingham single that defined the firm's late-1920s range.","image":"https://upload.wikimedia.org/wikipedia/commons/c/c6/1930_BSA_Model_30-7_500cc-side_valve_sloper_right_side.jpg"}];
  extra.forEach(function (x) {
    if (S.byId.has(x.id)) return;
    var c = { id: x.id, num: S.cards.length + 1, name: x.name, rarity: x.rarity,
              subtitle: x.subtitle, details: x.details, image: x.image, logo: '' };
    S.cards.push(c);
    S.byId.set(c.id, c);
    if (S.pools[c.rarity]) S.pools[c.rarity].push(c);
  });
})();
